    n = len(arr)
    if n == 0:
        return 0
    if n == 1:
        return arr[0]

    max_inc = arr[:]  # max product of increasing subsequence ending at i
    max_dec = arr[:]  # max product of decreasing subsequence ending at i

    max_prod = arr[0]

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                # Extend increasing subsequence from previous increasing subsequence
                if max_inc[j] * arr[i] > max_inc[i]:
                    max_inc[i] = max_inc[j] * arr[i]
                # Extend increasing subsequence from previous decreasing subsequence (e.g. negative to positive flip)
                if max_dec[j] * arr[i] > max_inc[i]:
                    max_inc[i] = max_dec[j] * arr[i]
            elif arr[i] < arr[j]:
                # Extend decreasing subsequence only from previous decreasing subsequence
                if max_dec[j] * arr[i] > max_dec[i]:
                    max_dec[i] = max_dec[j] * arr[i]
        max_prod = max(max_prod, max_inc[i])

