    num_cols = len(matrix[0])
    for row in matrix:
        if len(row) != num_cols:
            raise ValueError("All rows must have the same number of columns")
    if n >= num_cols:
        raise ValueError(f"Column index n={n} out of range for matrix columns={num_cols}")

    # Extract the nth column (0-based index)
    column = [row[n] for row in matrix]

    # Return max of the nth column
    return max(column)

