def validate(n):
    """
    Checks if the frequency of each digit in the integer is less than or equal to the digit itself.

    Args:
        n (int): The integer to validate.

    Returns:
        bool: True if the condition holds for all digits, False otherwise.
    """
    if not isinstance(n, int):
        return False

    s = str(n)
    if s.startswith('-'):
        return False

    digit_counts = {}
    for char in s:
        digit = int(char)
        digit_counts[digit] = digit_counts.get(digit, 0) + 1

    for digit, count in digit_counts.items():
        if count > digit:
            return False

    return True

