def max_product(arr):
    if not arr:
        return 0
    n = len(arr)
    max_prod = arr[0]
    # max_inc[i]: max product of increasing subsequence ending at i
    max_inc = arr[:]
    for i in range(1, n):
        max_inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and max_inc[j] * arr[i] > max_inc[i]:
                max_inc[i] = max_inc[j] * arr[i]
        if max_inc[i] > max_prod:
            max_prod = max_inc[i]
    return max_prod

