        raise ValueError("n must be at least 1")
    if len(matrix) == 0:
        raise ValueError("matrix must not be empty")
    # Check column index bounds, assume all rows have the same length
    row_len = len(matrix[0])
    if n > row_len:
        raise ValueError("n is out of column range")
    # Extract the nth column (1-based index to 0-based)
    column_values = [row[n-1] for row in matrix]
    return max(column_values)

