def find_first_occurrence(nums, target):
    if nums is None or target is None:
        return None
    if not nums:
        return None
    if target < nums[0] or target > nums[-1]:
        return None

    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            if mid == 0 or nums[mid - 1] < target:
                return mid
            right = mid - 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return None

