def pancake_sort(arr):
    arr = arr[:]  # Make a shallow copy to avoid mutating the input
    n = len(arr)

    def flip(sub_arr, k):
        i, j = 0, k
        while i < j:
            sub_arr[i], sub_arr[j] = sub_arr[j], sub_arr[i]
            i += 1
            j -= 1

    for size in range(n, 1, -1):
        max_idx = 0
        for i in range(1, size):
            if arr[i] > arr[max_idx]:
                max_idx = i
        if max_idx == size - 1:
            continue  # max already at correct position
        if max_idx != 0:
            flip(arr, max_idx)
        flip(arr, size - 1)
    return arr

