def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0
    if n == 1:
        return arr[0]

    max_inc = arr[:]
    min_inc = arr[:]

    max_overall = arr[0]

    for i in range(1, n):
        max_inc[i] = arr[i]
        min_inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                candidates = [arr[i], max_inc[j] * arr[i], min_inc[j] * arr[i]]
                max_val = max(candidates)
                min_val = min(candidates)
                if max_val > max_inc[i]:
                    max_inc[i] = max_val
                if min_val < min_inc[i]:
                    min_inc[i] = min_val
        if max_inc[i] > max_overall:
            max_overall = max_inc[i]

    return max_overall

def first_Digit(number):
    """
    Find the first digit of a given number.

    Args:
        number (int, float, or str): The number to extract the first digit from.

    Returns:
        int: The first digit of the number.
    """
    # Convert input to string
    s = str(number).strip()

    # Remove leading sign if present
    if s.startswith('-') or s.startswith('+'):
        s = s[1:]

    # Remove leading zeros and decimal points until first digit is found
    for ch in s:
        if ch.isdigit() and ch != '0':
            return int(ch)
        elif ch == '0':
            # Keep track if all leading zeros and decimal points so far
            continue
        elif ch == '.':
            continue
        elif ch.isdigit():
            return int(ch)

    # If no non-zero digit found, check if zero is present
    # This covers cases like "0", "0.0", "000"
    for ch in s:
        if ch.isdigit():
            return int(ch)

    # If no digits found at all, raise an error
    raise ValueError("No digits found in input")

