def dif_Square(n):
    # 0 can be represented trivially
    if n == 0:
        return True
    # Numbers congruent to 2 mod 4 cannot be expressed as difference of squares
    if n % 4 == 2:
        return False

    abs_n = abs(n)
    for d in range(1, int(abs_n**0.5) + 1):
        if abs_n % d == 0:
            x, y = d, abs_n // d
            # x and y must have the same parity to make a and b integers
            if (x % 2) == (y % 2):
                # Check if product can have the correct sign to get n
                # Since n = (a+b)(a-b) = x*y or (-x)*(-y) = x*y
                # For positive n, product x*y must be n
                # For negative n, product must be -abs_n, so check pairs with swapped sign
                if n > 0 and x * y == n:
                    return True
                if n < 0 and x * (-y) == n:
                    return True
                if n < 0 and (-x) * y == n:
                    return True
    return False

