        for j in range(i):
            if arr[j] < arr[i]:
                # If arr[i] can extend the subsequence ending at j
                # Update max_prod[i] with max of:
                # current max_prod[i]
                # max_prod[j] * arr[i]
                # min_prod[j] * arr[i] (if min_prod[j] negative and arr[i] negative, product can be positive and larger)
                max_candidate = max(max_prod[j] * arr[i], min_prod[j] * arr[i])
                min_candidate = min(max_prod[j] * arr[i], min_prod[j] * arr[i])
