    set2 = set(tuple2)
    result = []
    for item in tuple1:
        if item not in set2:
            result.append(item)
    return tuple(result)

def split_Arr(arr, n):
    if not arr:
        return arr
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if n >= len(arr):
        return arr
    return arr[n:] + arr[:n]

def max_of_nth(matrix, n):
    # Input Validation
    if not isinstance(matrix, list):
        raise TypeError("Input must be a list of lists")
    if not all(isinstance(row, list) for row in matrix):
        raise TypeError("All elements in the input must be lists")

    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")

    if n < 1 or n >= len(matrix):
        raise ValueError("n must be between 1 and the number of rows")

    # Extract the n'th column
    column = [row[n] for row in matrix]

    # Calculate and return the maximum
    return max(column)

def cummulative_sum(tuples):
    total = 0
    for t in tuples:
        for val in t:
            total += val
    return total

def find_first_occurrence(nums, target):
    if nums is None or target is None:
        return None
    if not nums:
        return None

    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            # Check if this is the first occurrence
            if mid == 0 or nums[mid - 1] < target:
                return mid
            # If nums[mid - 1] == target, we need to search left
            right = mid - 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return None

def sort_numeric_strings(nums):
    """
    Sorts a list of strings representing numbers numerically.
    """
    return sorted(nums, key=int)

def new_tuple(args, sep):
    if not args:
        return ()
    if len(args) == 1:
        return (args[0],)
    if not sep:
        raise ValueError("Separator cannot be empty")
    return tuple(args)

